    /// Each subpath's opacity, for icons that draw some fainter; nil
    /// when every path is drawn whole.
    public var opacities: [Double]? {
        switch self {
        case .fillLinear: return [1.0, 0.5, 0.5, 0.5, 1.0, 1.0, 0.75, 0.75, 1.0, 0.75]
        default: return nil
        }
    }
